  </div>{% endif %}
  {% else %}<div class="meta mt4">{% if last %}Last shot {{ g(last.time_s) }} s{% if last.taste %} · {{ last.taste }}{% endif %} · rated {{ last.rating }}{% else %}First shot of this {{ "bag" if p.bag else "coffee" }}{% endif %} · {% if p.water_temp_c %}{{ g(p.water_temp_c) }} °C, {% endif %}{{ p.brew_method }}{{ ", milk drink" if p.is_milk_drink }}</div>{% endif %}
  </div>
  <section class="fill" data-offline-saved data-name="{{ name }}" data-grinder="{{ gr.name }}" hidden>

